// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetActivity Stream recent searches and lookups
	// (GET /api/v1/activity)
	GetActivity(ctx context.Context, request GetActivityRequestObject) (GetActivityResponseObject, error)
	// ListAgents List the agents
	// (GET /api/v1/agents)
	ListAgents(ctx context.Context, request ListAgentsRequestObject) (ListAgentsResponseObject, error)
	// GetAgent Read one agent
	// (GET /api/v1/agents/{name})
	GetAgent(ctx context.Context, request GetAgentRequestObject) (GetAgentResponseObject, error)
	// GetArticle Look up one article
	// (GET /api/v1/articles/{id})
	GetArticle(ctx context.Context, request GetArticleRequestObject) (GetArticleResponseObject, error)
	// ListProjects List the registered Projects
	// (GET /api/v1/projects)
	ListProjects(ctx context.Context, request ListProjectsRequestObject) (ListProjectsResponseObject, error)
	// GetProject Read one registered Project
	// (GET /api/v1/projects/{id})
	GetProject(ctx context.Context, request GetProjectRequestObject) (GetProjectResponseObject, error)
	// GetProjectItems Export a Project's resolved view
	// (GET /api/v1/projects/{id}/items)
	GetProjectItems(ctx context.Context, request GetProjectItemsRequestObject) (GetProjectItemsResponseObject, error)
	// SearchArticles Search articles, skills and agents by keyword
	// (GET /api/v1/search)
	SearchArticles(ctx context.Context, request SearchArticlesRequestObject) (SearchArticlesResponseObject, error)
	// DeleteSession Sign out
	// (DELETE /api/v1/session)
	DeleteSession(ctx context.Context, request DeleteSessionRequestObject) (DeleteSessionResponseObject, error)
	// GetSession Read who the session cookie signs in
	// (GET /api/v1/session)
	GetSession(ctx context.Context, request GetSessionRequestObject) (GetSessionResponseObject, error)
	// PostSession Sign in with a token and get a session cookie
	// (POST /api/v1/session)
	PostSession(ctx context.Context, request PostSessionRequestObject) (PostSessionResponseObject, error)
	// ListSkills List the skills
	// (GET /api/v1/skills)
	ListSkills(ctx context.Context, request ListSkillsRequestObject) (ListSkillsResponseObject, error)
	// GetSkill Read one skill
	// (GET /api/v1/skills/{name})
	GetSkill(ctx context.Context, request GetSkillRequestObject) (GetSkillResponseObject, error)
	// GetSkillFile Read one file of a skill
	// (GET /api/v1/skills/{name}/files/{path})
	GetSkillFile(ctx context.Context, request GetSkillFileRequestObject) (GetSkillFileResponseObject, error)
	// GetSync Read the content sync status and warnings
	// (GET /api/v1/sync)
	GetSync(ctx context.Context, request GetSyncRequestObject) (GetSyncResponseObject, error)
	// PostSync Poll the Source now
	// (POST /api/v1/sync)
	PostSync(ctx context.Context, request PostSyncRequestObject) (PostSyncResponseObject, error)
	// GetOpenAPIJSON Get the OpenAPI document as JSON
	// (GET /openapi.json)
	GetOpenAPIJSON(ctx context.Context, request GetOpenAPIJSONRequestObject) (GetOpenAPIJSONResponseObject, error)
	// GetOpenAPIYAML Get the OpenAPI document as YAML
	// (GET /openapi.yaml)
	GetOpenAPIYAML(ctx context.Context, request GetOpenAPIYAMLRequestObject) (GetOpenAPIYAMLResponseObject, error)
}

// StrictHandlerFunc and StrictMiddlewareFunc are type aliases rather than
// distinct named types, so middleware written against one generated package
// can be shared with every other generated package using the same framework.
type StrictHandlerFunc = func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc = func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

